// EgressAgentServiceServer is the server API for EgressAgentService service.
// All implementations must embed UnimplementedEgressAgentServiceServer
// for forward compatibility.
type EgressAgentServiceServer interface {
	// Unary RPC to upload and safely reload sing-box configuration
	ApplyConfig(context.Context, *ConfigPayload) (*ConfigResponse, error)
	// Server Streaming RPC to continuously receive real-time node telemetry
	StreamTelemetry(*TelemetryRequest, grpc.ServerStreamingServer[TelemetryResponse]) error
	// Unary RPC to get immediate single snapshot telemetry
	GetTelemetry(context.Context, *TelemetryRequest) (*TelemetryResponse, error)
	// Unary RPC to trigger sing-box binary upgrade on the node
	UpgradeSingbox(context.Context, *UpgradePayload) (*UpgradeResponse, error)
	// Unary RPC to create/update one olcrtc instance's YAML config + systemd unit on the node —
	// idempotent (same shape write + restart every time, matching ConfigureAwg/ConfigureMeshTunnel).
	// Replaces the old ConfigureOlcrtc (proxied a third-party Olcrtc_manager admin daemon) — see plan
	// `olcrtc-redesign.md`, "Новая архитектура: собственный слой": route-agent now runs
	// olcrtc-agent-srv directly, one systemd unit per (user, node) instance, no admin HTTP surface.
	SyncOlcrtcInstance(context.Context, *OlcrtcInstanceConfigPayload) (*OlcrtcInstanceConfigResponse, error)
	// Unary RPC to stop+disable+remove one olcrtc instance's systemd unit + config.
	DeleteOlcrtcInstance(context.Context, *OlcrtcInstanceDeletePayload) (*OlcrtcInstanceConfigResponse, error)
	// Server Streaming RPC — one open stream per olcrtc-capable node, forwards every
	// session_open/session_close/traffic/health event across ALL instances running on that node in
	// real time, each event tagged with which instance/user it belongs to. Doesn't fit
	// TelemetryResponse's flat per-node-scalar shape (event-driven/high-frequency, not a periodic
	// snapshot) — mirrors StreamTelemetry's per-node-stream shape instead. Source: olcrtc-agent-srv's
	// own stdout JSON lines (see that repo's events.go), tailed off each instance's systemd journal.
	StreamOlcrtcEvents(*OlcrtcEventsRequest, grpc.ServerStreamingServer[OlcrtcEvent]) error
	// Unary RPC to trigger agent self-update from repository
	SelfUpdate(context.Context, *SelfUpdatePayload) (*SelfUpdateResponse, error)
	// Client Streaming RPC to stream binary payload to the node agent
	UploadSingboxBinary(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Client Streaming RPC to stream AWG Tools (awg) binary to the node agent
	UploadAwgToolsBinary(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Client Streaming RPC to stream AWG Go Core (amneziawg-go) binary to the node agent
	UploadAwgGoBinary(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Client Streaming RPC to stream a custom-built Caddy binary (caddy-dns/cloudflare plugin) to the node agent — Xeon-ring nodes only
	UploadCaddyBinary(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Client Streaming RPC to stream the mihomo binary — the REAR core. Rear-capable nodes only.
	//
	// Separate from UploadSingboxBinary because these are two different binaries with two different
	// jobs on the same node: sing-box serves subscribers at the front, mihomo carries the rear WARP
	// branch. Sharing one RPC would mean a target_binary discriminator whose two values install to
	// different paths, run under different units and fail for different reasons.
	UploadMihomoBinary(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Client Streaming RPC to deliver ONE rule set for the rear (MetaCubeX .mrs) to the node.
	//
	// The node never fetches these itself. A hosted node reaching out to github.com recreates the
	// very traffic anomaly the tunnel exists to remove: a box that only accepts subscribers looks
	// nothing like a box that also pulls from code-hosting. Fetching outward is the orchestrator's
	// job alone; the node only ever receives.
	//
	// The set name travels in target_binary — see the field comment on BinaryChunkPayload.
	UploadRearRuleSet(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Наблюдение за трафиком AmneziaWG.
	//
	// ЗАЧЕМ ОТДЕЛЬНЫЙ ВЫЗОВ, если есть GetSingBoxConnections. Клиентский AWG уходит с узла ядерным
	// NAT-ом, МИНУЯ sing-box: `устройство -> awg0 -> ядро -> интернет`. В таблице соединений
	// sing-box этого трафика нет по построению, поэтому абоненты на AWG были вне контура
	// наблюдения целиком — ни снимков, ни ограничения.
	//
	// Источников два и они разной надёжности: счётчики пиров есть всегда, соединения ядра дают
	// форму потока. Подробности — в комментариях к AwgObservationResponse.
	GetAwgObservation(context.Context, *AwgObservationRequest) (*AwgObservationResponse, error)
	// Unary RPC for AmneziaWG3 service management
	ConfigureAwg(context.Context, *AwgConfigPayload) (*AwgConfigResponse, error)
	// Unary RPC to configure Caddy (TLS certificates manager)
	ConfigureCaddy(context.Context, *CaddyConfigPayload) (*CaddyConfigResponse, error)
	// Client Streaming RPC to stream the olcrtc-agent-srv binary to the node agent — replaces the old
	// UploadOlcrtcBinary (uploaded the third-party Olcrtc_manager binary, no longer used).
	UploadOlcrtcAgentSrvBinary(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Client Streaming RPC to stream the AmneziaWG kernel-module SOURCE tarball (S2S mesh tunnel,
	// front↔egress, second ring-relay hop) to the node agent — fetched centrally by the
	// orchestrator (never git-cloned by the node itself, see githubService.ts's
	// ensureAwgKernelModuleSource — a RF-hosted node reaching github.com directly would recreate
	// the exact SNI/IP DPI-visibility risk this whole tunnel exists to avoid). On the final chunk
	// the agent extracts the tarball and builds it locally via DKMS against its own running
	// kernel — a kernel module can't be cross-compiled centrally like the other Upload*Binary RPCs.
	UploadMeshAwgKernelSource(grpc.ClientStreamingServer[BinaryChunkPayload, UploadBinaryResponse]) error
	// Unary RPC to configure/reload the S2S AmneziaWG3 mesh-tunnel interface (front↔egress, second
	// ring-relay hop) — distinct from ConfigureAwg (client-facing AWG service, different interface,
	// different key material). Reuses the already-delivered awg/awg-quick tools (UploadAwgToolsBinary)
	// — once the kernel module is loaded, awg-quick drives it directly via netlink, no separate
	// userspace core needed for this interface.
	ConfigureMeshTunnel(context.Context, *MeshTunnelConfigPayload) (*MeshTunnelConfigResponse, error)
	// Unary RPC for dynamic firewall management on node
	ManageFirewall(context.Context, *FirewallPayload) (*FirewallResponse, error)
	// Unary RPC to query agent version & protocol contract hash
	GetAgentInfo(context.Context, *AgentInfoRequest) (*AgentInfoResponse, error)
	RunNetworkDiagnostic(context.Context, *NetworkDiagnosticRequest) (*NetworkDiagnosticResponse, error)
	// Unary RPC to read a Caddy-managed certificate's PEM content off disk (Xeon-ring wildcard
	// cert courier: orchestrator polls this after DNS-01 issuance, then relays the result to
	// every egress node behind that front via ConfigureCaddy's extra_cert_pem/extra_key_pem)
	GetManagedCertificate(context.Context, *CertificateRequest) (*CertificateResponse, error)
	// Unary RPC to fetch per-user traffic deltas from sing-box's OWN local V2Ray-API-compatible
	// stats service (experimental.v2ray_api, loopback-only — see egressSingbox.ts's generator and
	// the tuic/hysteria2 inbound `users[].name` field, set to our own user uuid so sing-box's
	// `user>>>{name}>>>traffic>>>uplink/downlink` counters map back to it directly). Route-agent
	// reads the currently-applied sing-box config off disk to find the live listen address, dials
	// it locally, and returns already-parsed per-user deltas — the orchestrator never talks to
	// sing-box directly, and no new port is exposed publicly anywhere. Watcher v2 "Track B-lite"
	// (2026-08-19) — a decoy-only, corroboration-gated traffic-anomaly signal for tuic/hy2Sb,
	// mirroring Track A's Remnawave-bandwidth-stats signal for VLESS/hy2Rw. See watcher's own
	// CLAUDE.md for the confidence/tier cap this must never exceed.
	GetSingBoxUserTraffic(context.Context, *SingBoxUserTrafficRequest) (*SingBoxUserTrafficResponse, error)
	// Unary RPC to fetch per-connection records from sing-box's OWN local Clash API
	// (experimental.clash_api, loopback-only — see shared/utils/clashApi.ts for why this replaced
	// the previous v2ray_api channel: `with_v2ray_api` is absent from official sing-box release
	// builds, so a config carrying that block failed `sing-box check` outright).
	//
	// Route-agent reads the currently-applied sing-box config off disk to find the live
	// external_controller address and secret, dials it locally and returns already-parsed records —
	// the orchestrator never talks to sing-box directly and no new port is exposed publicly.
	//
	// ONE RPC serves BOTH node kinds, because the same agent runs on both. Which fields come back
	// populated differs, and that difference is the point:
	//   - egress node: `user` is set (tuic/hy2 inbounds put the authenticated user into
	//     metadata.User) and `destination_*` is the real target;
	//   - Xeon front: `user` is EMPTY — a blind SNI relay authenticates nobody — but `source_ip` is
	//     the real client address, which the egress side can never see after the relay (see the
	//     "real-IP-through-relay" entry in BACKLOG.md).
	//
	// The two halves are therefore analysed separately and never need to be joined.
	GetSingBoxConnections(context.Context, *SingBoxConnectionsRequest) (*SingBoxConnectionsResponse, error)
	// Соединения ТЫЛОВОГО ядра (mihomo) — тот же контракт сообщений, другой источник.
	//
	// ЗАЧЕМ ОТДЕЛЬНЫЙ ВЫЗОВ. Тыл стоит на хоп ДАЛЬШЕ фронтового sing-box и видит то, чего не видит
	// никто другой: НАСТОЯЩЕЕ внешнее назначение. У фронта назначение — это кольцо, у эгресса —
	// петля на локальный порт, и лишь тыл маршрутизирует по реальному адресу, а значит знает его
	// точно, а не по сниффингу наугад.
	//
	// ЧЕГО ЗДЕСЬ НЕТ И НЕ БУДЕТ: абонента. Эгресс ходит в тыл одним исходящим VLESS с ОДНИМ uuid на
	// всех, поэтому `user` у всех записей одинаков (`link`). Это не недоделка сбора, а следствие
	// устройства связки — см. BACKLOG.md, «полная видимость на тылу».
	//
	// Поэтому разбор по этим записям АГРЕГАТНЫЙ: «куда льётся поток с узла», а не «кто льёт». Ровно
	// это и требовалось исходной задаче про поток к одному назначению — наказывается направление, а
	// не абонент.
	GetRearConnections(context.Context, *SingBoxConnectionsRequest) (*SingBoxConnectionsResponse, error)
	// Unary RPC that brings the node's source-prefix rate limiting to the requested state and
	// returns the drop counters observed BEFORE that change.
	//
	// Enforced with a tc INGRESS policer, not an egress shaper: a mark on an incoming packet does
	// not carry over to the outgoing socket (sing-box terminates the connection and opens a new one
	// to the destination — which is exactly why it has its own routing_mark). So a source-based
	// limit applies to the "client -> us" leg, and that is enough: what a subscriber cannot push
	// into us, it cannot push onward either.
	//
	// The drops are half the point, not a side effect. Measured on a live kernel under one and the
	// same policer: cooperative TCP produced 122 drops in six seconds, a non-cooperative UDP flood
	// produced 1,791,515 (99.76% of what it sent, while still sending at full speed). Four orders of
	// magnitude apart — "keeps hammering despite loss" separates a flood from a large download by
	// BEHAVIOUR rather than volume, and that can only be learned by applying back-pressure.
	//
	// Counters are read before re-applying because rebuilding the filters resets them. The agent
	// therefore skips the rebuild entirely when the list, rate and burst are unchanged — otherwise
	// every delivery would erase the very evidence the escalation decision rests on.
	ApplyTrafficThrottle(context.Context, *TrafficThrottleRequest) (*TrafficThrottleResponse, error)
	// Unary RPC that brings the node's REAR sing-box instance to the requested state.
	//
	// A SECOND sing-box process on the same node, alongside the front one that terminates
	// subscribers. The front decides who may connect; the rear decides where their traffic goes —
	// "stars" wrapped into Cloudflare WARP, "games" straight out — and doubles as the point where
	// outbound direction is observed (its own Clash API, read the same way the front's already is,
	// see GetSingBoxConnections).
	//
	// ONE BINARY, TWO UNITS. The rear reuses the sing-box binary already installed for the front,
	// so UpgradeSingbox and SelfUpdate keep covering both and no second update path exists to drift.
	// The consequence is a hard precondition: with no sing-box installed there is nothing to run,
	// and the agent answers with skipped_reason instead of an error (the orchestrator does not even
	// offer the button in that case).
	//
	// The agent MUST run `sing-box check` on config_json before applying it. Writing an invalid
	// config and restarting would take down a working rear instance, and the branch that was
	// flowing through WARP would stop rather than degrade.
	ConfigureRearSingbox(context.Context, *RearSingboxConfigPayload) (*RearSingboxConfigResponse, error)
	// Unary RPC that reports the health of this node's WARP keys, read from the REAR sing-box's own
	// local Clash API (experimental.clash_api, loopback-only — same channel and same rationale as
	// GetSingBoxConnections, but pointed at the rear instance rather than the front one).
	//
	// THE MEASUREMENTS ARE NOT TAKEN HERE, AND THAT IS THE POINT. The rear config puts every WARP
	// endpoint into a urltest group, so sing-box already probes each of them on its own schedule and
	// keeps the result. Clash API's /proxies lists endpoints alongside outbounds and hands back that
	// stored history, so the agent only reads what has already been measured — no extra traffic on a
	// link the owner pays for by the byte. An empty history means the last probe FAILED: sing-box
	// deletes the entry on error and stores one on success.
	//
	// What this can and cannot see: it detects a key that is unreachable or slow. It does NOT
	// reliably detect a key Cloudflare has THROTTLED — throttling shows up as degraded throughput,
	// and measuring throughput was ruled out as too expensive. Treat a healthy report as "the tunnel
	// answers", not as "the key is at full speed".
	GetWarpKeyHealth(context.Context, *WarpKeyHealthRequest) (*WarpKeyHealthResponse, error)
	// Unary RPC that reports warnings found in this node's own journals — the class of problem where
	// everything WORKS but works worse than it should, and nothing ever surfaces it.
	//
	// WHY THE AGENT AND NOT THE ORCHESTRATOR. Telemetry already streams a tail of the sing-box
	// journal, so scanning it centrally looks tempting. It does not work: the tail is a few kilobytes,
	// and the warnings that matter most are printed ONCE at socket setup, so on a busy node they
	// scroll out of that window within seconds. Only the node can look back over hours of its own
	// journal, and journalctl's own --grep keeps the cost on the node instead of shipping megabytes.
	//
	// STATELESS ON PURPOSE. The agent reports every distinct warning class currently visible in a
	// fixed lookback window, with a count and the last occurrence — it does NOT track what it already
	// said. A journal cursor would have to be persisted, kept in sync with an unknown number of
	// consumers, and would silently swallow a warning whenever it drifted. Deduplication belongs to
	// the orchestrator, which is the side that actually decides whether to notify a human.
	PullNodeWarnings(context.Context, *NodeWarningsRequest) (*NodeWarningsResponse, error)
	mustEmbedUnimplementedEgressAgentServiceServer()
}

